(5640884, 818019, 104537, '<td valign="top">This is beautiful your use of light and color combinations has a very nostalgic feel to this one. Very nice image</td>', 'This is beautiful your use of light and color combinations has a very nostalgic feel to this one. Very nice image', '2009-09-08 20:47:35.000000', NULL, 1),
(5640886, 817632, 104537, '<td valign="top">This is cute.</td>', 'This is cute.', '2009-09-08 20:47:55.000000', NULL, 1),
(5640887, 818652, 104537, '<td valign="top">Very nice composition. The color and the green really add to this image.</td>', 'Very nice composition. The color and the green really add to this image.', '2009-09-08 20:49:08.000000', NULL, 1),
(5641005, 818786, 2553, '<td valign="top">Really love this!  The concept is adorable and you carried it out well.  Definitely one of my favs; expect to see this on the front page.</td>', 'Really love this!  The concept is adorable and you carried it out well.  Definitely one of my favs; expect to see this on the front page.', '2009-09-08 22:34:29.000000', NULL, 1),
(5641006, 818754, 2553, '<td valign="top">Not what I really pictured as a Veggie Tale, but a nice shot of veggies none-the-less.</td>', 'Not what I really pictured as a Veggie Tale, but a nice shot of veggies none-the-less.', '2009-09-08 22:34:36.000000', NULL, 1),
(5641007, 818060, 2553, '<td valign="top">I was really looking more for "scenes" made up of veggies for this challenge, but this is an interesting veggie shot.</td>', 'I was really looking more for "scenes" made up of veggies for this challenge, but this is an interesting veggie shot.', '2009-09-08 22:34:40.000000', NULL, 1),
(5641008, 818019, 2553, '<td valign="top">My concept of this challenge leans a bit more in the direction of a "scene" made up of fruits and veggies, however, this is a very nicely done image.</td>', 'My concept of this challenge leans a bit more in the direction of a "scene" made up of fruits and veggies, however, this is a very nicely done image.', '2009-09-08 22:34:43.000000', NULL, 1),
(5641009, 818528, 2553, '<td valign="top">Not what I was picturing as the type of thing that would fit "Veggie Tales", but I really do like this image a lot.  I find the image very pleasing, and will score it high for that reason.</td>', 'Not what I was picturing as the type of thing that would fit "Veggie Tales", but I really do like this image a lot.  I find the image very pleasing, and will score it high for that reason.', '2009-09-08 22:34:48.000000', NULL, 1),
(5641010, 818305, 2553, '<td valign="top">A nicely done image, and I am judging it on its own merits; however, my interpretation of "Veggie Tales" was a bit different.  I was looking more for "scenes" created from veggies and fruits.</td>', 'A nicely done image, and I am judging it on its own merits; however, my interpretation of "Veggie Tales" was a bit different.  I was looking more for "scenes" created from veggies and fruits.', '2009-09-08 22:34:51.000000', NULL, 1),
(5641013, 817776, 2553, '<td valign="top">Adorable, and exactly the kind of thing that I had in mind when thinking of "Veggie Tales"  -  a "scene"!  Really cute and creative!</td>', 'Adorable, and exactly the kind of thing that I had in mind when thinking of "Veggie Tales"  -  a "scene"!  Really cute and creative!', '2009-09-08 22:35:06.000000', NULL, 1),
(5641014, 818628, 2553, '<td valign="top">Wow, very different and very creative.  It definitely fits what I felt the challenge was looking for more than many of the entries.</td>', 'Wow, very different and very creative.  It definitely fits what I felt the challenge was looking for more than many of the entries.', '2009-09-08 22:35:20.000000', NULL, 1),
(5641015, 818818, 2553, '<td valign="top">Though not a "scene" (which is what I was picturing as the idea for this challenge) really, I like this very much.  It''s well captured and definitely conveys the spirit of emotion.</td>', 'Though not a "scene" (which is what I was picturing as the idea for this challenge) really, I like this very much.  It''s well captured and definitely conveys the spirit of emotion.', '2009-09-08 22:35:23.000000', NULL, 1),
(5641020, 818057, 2553, '<td valign="top">Yes, a scene!  This is definitely the kind of thing I was thinking about for this challenge.  This does feel like another galaxy!  Very clever use of the artichokes.</td>', 'Yes, a scene!  This is definitely the kind of thing I was thinking about for this challenge.  This does feel like another galaxy!  Very clever use of the artichokes.', '2009-09-08 22:36:43.000000', NULL, 1),
(5641021, 817632, 2553, '<td valign="top">Hahaha; this isn''t exactly the kind of scene that I was thinking about, but it is cute and funny!</td>', 'Hahaha; this isn''t exactly the kind of scene that I was thinking about, but it is cute and funny!', '2009-09-08 22:36:54.000000', NULL, 1),
(5641022, 818789, 2553, '<td valign="top">The turtle is hilarious, and so cute.  I would never have thought of an underwater scene, good imagination.</td>', 'The turtle is hilarious, and so cute.  I would never have thought of an underwater scene, good imagination.', '2009-09-08 22:37:24.000000', NULL, 1),
